    "path": "manifest.json",
    "content": "{\n  \"slug\": \"ninety9-archive\",\n  \"id\": \"ninety9-archive\",\n  \"name\": \"ninety9-archive\",\n  \"title\": \"NINETY9 — The Monochrome Archive of the 1990s\",\n  \"description\": \"Application #2 built with Kiro + GenUI: 1997 NeXT/Macintosh paper-white monochrome editorial workstation publication archiving 34 historical artifacts across 12 sectors and 1990-1999 decade milestones, featuring toggleable CRT scanlines, 99.4 MHz random packet transmission, and Zod-verified live monochrome remixes.\",\n  \"mode\": \"native\",\n  \"version\": \"1.0.0\",\n  \"author\": \"WizFrame\",\n  \"license\": \"MIT\",\n  \"tier\": \"free\",\n  \"priceUsd\": 0,\n  \"category\": \"Editorial / Archive\",\n  \"tags\": [\n    \"Editorial\",\n    \"Monochrome\",\n    \"Next.js 15\",\n    \"GenUI Verified\"\n  ],\n  \"verified\": true,\n  \"featured\": true,\n  \"immersiveExperience\": true,\n  \"publicAssetsPrefix\": \"images/ninety9\",\n  \"theme\": {\n    \"defaultColorScheme\": \"light\",\n    \"accentColor\": \"#000000\",\n    \"surfaceBg\": \"#FFFFFF\",\n    \"surfaceElevated\": \"#D9D9D9\",\n    \"textColor\": \"#000000\",\n    \"mutedColor\": \"#292929\",\n    \"displayFont\": \"\\\"Space Mono\\\", \\\"Courier New\\\", monospace\",\n    \"bodyFont\": \"\\\"Inter\\\", system-ui, sans-serif\",\n    \"borderRadius\": \"0px\"\n  },\n  \"pages\": [\n    {\n      \"id\": \"home\",\n      \"slug\": \"home\",\n      \"title\": \"NINETY9 · [00] Workstation Home\",\n      \"route\": \"/\",\n      \"description\": \"Paper-white editorial masthead, featured artifact split, 12-sector directory, 1990-1999 timeline preview, and 99.4 MHz random packet transmitter.\",\n      \"sections\": [\n        \"WorkstationFrame\",\n        \"HeroSection\",\n        \"FeaturedSection\",\n        \"CategoryGrid\",\n        \"TimelinePreview\",\n        \"RandomTransmit\",\n        \"ArchiveCatalogMatrix\"\n      ]\n    },\n    {\n      \"id\": \"archive\",\n      \"slug\": \"archive\",\n      \"title\": \"NINETY9 · [01] Searchable Archive Catalog\",\n      \"route\": \"/archive\",\n      \"description\": \"Multi-facet searchable index of all 34 1990s artifacts with 1990-1999 year pills, sector/type selectors, sort order, and interactive dossier reader.\",\n      \"sections\": [\n        \"WorkstationFrame\",\n        \"ArchiveCatalogMatrix\",\n        \"DossierReaderView\"\n      ]\n    },\n    {\n      \"id\": \"timeline\",\n      \"slug\": \"timeline\",\n      \"title\": \"NINETY9 · [02] 1990-1999 Decade Timeline\",\n      \"route\": \"/timeline\",\n      \"description\": \"Chronological quarterly ledger linking 1990-1999 cultural and hardware breakthroughs directly to indexed dossiers.\",\n      \"sections\": [\n        \"WorkstationFrame\",\n        \"TimelinePreview\"\n      ]\n    },\n    {\n      \"id\": \"categories\",\n      \"slug\": \"categories\",\n      \"title\": \"NINETY9 · [03] Sector Essays & Index\",\n      \"route\": \"/categories\",\n      \"description\": \"Long-form essays, decade shift notes, and monochrome schematic plates across all 12 archival sectors.\",\n      \"sections\": [\n        \"WorkstationFrame\",\n        \"ArchiveCatalogMatrix\"\n      ]\n    },\n    {\n      \"id\": \"about\",\n      \"slug\": \"about\",\n      \"title\": \"NINETY9 · [04] Manifesto & Spec Sheet\",\n      \"route\": \"/about\",\n      \"description\": \"1997 Paper-White workstation colophon, 5-tone monochrome hex specimen, and CRT scanline calibration.\",\n      \"sections\": [\n        \"WorkstationFrame\",\n        \"ArchiveCatalogMatrix\"\n      ]\n    },\n    {\n      \"id\": \"arcade\",\n      \"slug\": \"arcade\",\n      \"title\": \"NINETY9 · [05] Workstation Arcade\",\n      \"route\": \"/arcade\",\n      \"description\": \"Playable 1-bit monochrome arcade bay featuring Serpent-98, Break-Grid, and Packet Invaders with Web Audio SFX and local high-score persistence.\",\n      \"sections\": [\n        \"WorkstationFrame\",\n        \"ArcadeCabinetSection\"\n      ]\n    }\n  ],\n  \"remixPresets\": [\n    {\n      \"id\": \"arcade-1998\",\n      \"label\": \"Remix Layout: 1998 NINETY9 Arcade Edition (Focus: Packet Invaders & Break-Grid)\",\n      \"description\": \"Boots straight into the [05] Arcade Bay in Turbo Y2K CRT mode with tuned physics bounds and 5-row corrupted packet waves.\",\n      \"prompt\": \"Remix Layout: 1998 NINETY9 Arcade Edition (Focus: Packet Invaders & Break-Grid)\"\n    },\n    {\n      \"id\": \"cyber-hardware-1995\",\n      \"label\": \"Remix Layout: 1995 Cyber-Hardware Special Issue (Focus: Technology & Gaming)\",\n      \"description\": \"Pivots the lead masthead, featured plates, timeline year, and recent feed onto 1995 silicon hardware and 32-bit gaming.\",\n      \"prompt\": \"Remix Layout: 1995 Cyber-Hardware Special Issue (Focus: Technology & Gaming)\"\n    },\n    {\n      \"id\": \"underground-zine-1991\",\n      \"label\": \"Remix Layout: 1991 Underground Zine Edition (Focus: Music & Cinema)\",\n      \"description\": \"Configures the workstation issue around 1991 photocopied DIY zine culture, grunge albums, and independent celluloid.\",\n      \"prompt\": \"Remix Layout: 1991 Underground Zine Edition (Focus: Music & Cinema)\"\n    },\n    {\n      \"id\": \"chaos-monochrome-heal\",\n      \"label\": \"Inject Corrupted Non-Monochrome / Invalid Year Packet\",\n      \"description\": \"Injects off-palette neon colors and invalid year 2045 JSONL packets to verify @genui-studio/core real-time schema healing.\",\n      \"prompt\": \"Inject Corrupted Non-Monochrome / Invalid Year Packet\"\n    }\n  ],\n  \"dependencies\": {\n    \"zustand\": \"^5.1.0\"\n  },\n  \"devDependencies\": {}\n}\n",
